const trip = { id: 'trip', name: 'Ski trip', members: ['Ann', 'Ben', 'Cara'] }
const all = ['Ann', 'Ben', 'Cara']
const readJson = file => JSON.parse(readFileSync(file, 'utf8'))

async function withFile(fn) {
  const data = tempDataFile()
  try {
    await fn(data.file)
  } finally {
    data.cleanup()
  }
}

async function withAppOn(file, fn) {
  const app = await startApp(file)
  try {
    await fn(app.call)
  } finally {
    await app.stop()
  }
}

test('an expense of 4.35 is shown as 4.35 and stored as 435 cents', () => withFile(file => withAppOn(file, async call => {
  await call('POST', '/groups', trip)
  const r = await call('POST', '/groups/trip/expenses', { description: 'Lunch', payer: 'Ann', amount: 4.35 })
  assert.equal(r.status, 201)
  assert.equal(r.body.amount, 4.35)
  assert.equal((await call('GET', '/groups/trip/expenses')).body[0].amount, 4.35)
  assert.equal(readJson(file).expenses[0].amount, 435)
})))

test('a payment of 4.35 is shown as 4.35 and stored as 435 cents', () => withFile(file => withAppOn(file, async call => {
  await call('POST', '/groups', trip)
  const r = await call('POST', '/groups/trip/payments', { from: 'Ben', to: 'Ann', amount: 4.35 })
  assert.equal(r.status, 201)
  assert.equal(r.body.amount, 4.35)
  assert.equal((await call('GET', '/groups/trip/payments')).body[0].amount, 4.35)
  assert.equal(readJson(file).payments[0].amount, 435)
})))

test('an expense of 10 split three ways gives the extra cent to the first in the split', () => withApp(async call => {
  await call('POST', '/groups', trip)
  const first = await call('POST', '/groups/trip/expenses', { description: 'Taxi', payer: 'Ann', amount: 10 })
  assert.deepEqual(first.body.shares, { Ann: 3.34, Ben: 3.33, Cara: 3.33 })
  const second = await call('POST', '/groups/trip/expenses', { description: 'Bus', payer: 'Ann', amount: 10, split: ['Cara', 'Ann', 'Ben'] })
  assert.deepEqual(second.body.shares, { Cara: 3.34, Ann: 3.33, Ben: 3.33 })
}))

test('balances after a 10 expense paid by Ann are 6.66, -3.33 and -3.33', () => withApp(async call => {
  await call('POST', '/groups', trip)
  await call('POST', '/groups/trip/expenses', { description: 'Taxi', payer: 'Ann', amount: 10 })
  assert.deepEqual((await call('GET', '/groups/trip/balances')).body, { balances: { Ann: 6.66, Ben: -3.33, Cara: -3.33 } })
}))

test('balances add up to exactly 0 cents after several uneven expenses', () => withApp(async call => {
  await call('POST', '/groups', trip)
  const expenses = [
    { description: 'A', payer: 'Ann', amount: 10 },
    { description: 'B', payer: 'Ben', amount: 0.01 },
    { description: 'C', payer: 'Cara', amount: 7.77, split: ['Ben', 'Cara'] },
    { description: 'D', payer: 'Ben', amount: 100, split: all },
  ]
  for (const e of expenses) assert.equal((await call('POST', '/groups/trip/expenses', e)).status, 201, e.description)
  const { balances } = (await call('GET', '/groups/trip/balances')).body
  const sum = Object.values(balances).reduce((a, b) => a + b, 0)
  assert.equal(Math.round(sum * 100), 0)
}))

test('settle-up after a 10 expense paid by Ann has Ben and Cara each pay 3.33', () => withApp(async call => {
  await call('POST', '/groups', trip)
  await call('POST', '/groups/trip/expenses', { description: 'Taxi', payer: 'Ann', amount: 10 })
  assert.deepEqual((await call('GET', '/groups/trip/settle-up')).body, {
    payments: [{ from: 'Ben', to: 'Ann', amount: 3.33 }, { from: 'Cara', to: 'Ann', amount: 3.33 }],
  })
}))

function oldFileText() {
  return JSON.stringify({
    groups: [trip],
    expenses: [{ id: 1, group: 'trip', description: 'Taxi', payer: 'Ann', amount: 434, split: all }],
    payments: [],
    nextExpenseId: 2,
    nextPaymentId: 1,
  })
}

test('an existing file with 434 cents is read as 4.34 and is not changed by a GET', () => withFile(file => {
  writeFileSync(file, oldFileText())
  return withAppOn(file, async call => {
    const r = await call('GET', '/groups/trip/expenses')
    assert.equal(r.body[0].amount, 4.34)
    assert.deepEqual(r.body[0].shares, { Ann: 1.45, Ben: 1.45, Cara: 1.44 })
    assert.equal(readFileSync(file, 'utf8'), oldFileText())
  })
}))

test('adding an expense leaves the stored 434 cents of an older expense alone', () => withFile(file => {
  writeFileSync(file, oldFileText())
  return withAppOn(file, async call => {
    const r = await call('POST', '/groups/trip/expenses', { description: 'Bus', payer: 'Ben', amount: 4.35 })
    assert.equal(r.status, 201)
    const saved = readJson(file)
    assert.equal(saved.expenses[0].amount, 434)
    assert.equal(saved.expenses[1].amount, 435)
  })
}))
